from pathlib import Path

import click
import udsoncan
from loguru import logger
from udsoncan.services import DiagnosticSessionControl

from test_ark.qh01.doip import DoIP

# 一个示例：https://holomatic.feishu.cn/docx/M443dq4OComYt8xyOsocUIfbnpd
VCI = ""  # noqa: E501


def main(data_file: str):
    with DoIP() as doip:
        doip.client.change_session(DiagnosticSessionControl.Session.extendedDiagnosticSession)
        doip.client.unlock_security_access(1)

        response = doip.client.read_data_by_identifier(udsoncan.DataIdentifier.VIN)
        logger.info(f"VIN码：{response.get_payload().hex()}")

        response = doip.client.read_data_by_identifier(0xF011)
        logger.info(f"整车配置字：{response.get_payload().hex()}")

        if data_file and Path(data_file).exists():
            logger.warning("更新整车配置字...")
            doip.client.write_data_by_identifier(0xF011, bytes.fromhex(Path(data_file).read_text().strip()))

            response = doip.client.read_data_by_identifier(0xF011)
            logger.info(f"整车配置字：{response.get_payload().hex()}")


@click.command()
@click.option(
    "--data-file",
    type=str,
    help="车型配置数据文件路径",
)
def cli(data_file: str) -> None:
    """整车配置字读写"""
    main(data_file=data_file)


if __name__ == "__main__":
    cli()
